// Single source of truth for pages that were merged into another page.
// Every key is 301-redirected (public/.htaccess, generated by prerender.js) to its value,
// is not pre-rendered, is left out of every sitemap and is never linked internally.
const CITY_DUPLICATES = {
  // City pages that rendered the same content as another city page
  '/market-area/tuticorin/': '/market-area/thoothukudi/',
  '/market-area/bharuch/': '/market-area/dahej/',
  '/market-area/chittoor-tirupati/': '/market-area/tirupati/',
  '/market-area/vijayawada-guntur/': '/market-area/vijayawada/'
};

// City x product and industry x city EP pages: merged into the single city page
const cityMerges = {
  hyderabad: ['electropolished-pipes-in-hyderabad', 'ss-316l-electropolished-pipes-in-hyderabad', 'electropolished-pipe-fittings-in-hyderabad', 'pharmaceutical-electropolished-pipes-hyderabad'],
  pune: ['electropolished-pipes-in-pune', 'ss-316l-electropolished-pipes-in-pune', 'electropolished-pipe-fittings-in-pune', 'pharmaceutical-electropolished-pipes-pune', 'dairy-electropolished-pipes-pune'],
  ahmedabad: ['electropolished-pipes-in-ahmedabad', 'ss-316l-electropolished-pipes-in-ahmedabad', 'pharmaceutical-electropolished-pipes-ahmedabad'],
  bengaluru: ['electropolished-pipes-in-bengaluru', 'ultra-high-purity-ep-tubes-in-bengaluru', 'biotech-electropolished-pipes-bengaluru', 'semiconductor-electropolished-pipes-bengaluru'],
  chennai: ['electropolished-pipes-in-chennai'],
  vadodara: ['electropolished-pipes-in-vadodara'],
  visakhapatnam: ['electropolished-pipes-in-visakhapatnam'],
  mumbai: ['electropolished-pipes-in-mumbai', 'ss-316l-electropolished-pipes-in-mumbai'],
  anand: ['dairy-electropolished-pipes-anand'],
  kolhapur: ['dairy-electropolished-pipes-kolhapur'],
  tirupati: ['mango-pulp-electropolished-pipes-chittoor-tirupati'],
  vijayawada: ['mango-pulp-electropolished-pipes-vijayawada-guntur'],
  sangareddy: ['brewery-electropolished-pipes-sangareddy'],
  nashik: ['food-processing-electropolished-pipes-nashik']
};

// Overlapping EP product pages: merged into the one page that targets that keyword
const productMerges = {
  '/astm-a270-electropolished-tubes/': ['/astm-a270-sanitary-tube/', '/electropolished-pipes/astm-a270-sanitary-tube/'],
  '/asme-bpe-electropolished-tubes/': ['/electropolished-pipes/asme-bpe-tube/'],
  '/ss-316l-electropolished-pipes/': ['/electropolished-pipes/ss-316-316l-electropolished-pipe/', '/ss316-electro-polish-pipe/', '/ss316l-electro-polish-pipe/'],
  '/ss-304l-electropolished-pipes/': ['/electropolished-pipes/ss-304-304l-electropolished-pipe/', '/304-stainless-steel-electropolish-pipe/'],
  '/electropolished-seamless-pipes/': ['/ss304-seamless-electro-polish-pipe/', '/ss304l-seamless-electro-polish-pipe/'],
  '/electropolished-welded-erw-pipes/': ['/ss304-welded-electro-polish-pipe/', '/ss316-welded-electro-polish-pipe/', '/ss316l-welded-electro-polish-pipe/'],
  '/electropolished-pipes/duplex-electropolished-pipe/': ['/duplex-electro-polish-pipe/', '/super-duplex-electro-polish-pipe/', '/duplex-electro-polish-seamless-pipe/', '/super-duplex-electro-polish-seamless-pipe/'],
  '/electropolished-pipes/': ['/ss-electropolish-pipe/'],
  '/electropolished-pipe-fittings/': ['/electropolished-pipes/electropolished-pipe-and-fittings/']
};

export const REDIRECTED_PATHS = { ...CITY_DUPLICATES };
for (const [city, slugs] of Object.entries(cityMerges)) {
  for (const slug of slugs) REDIRECTED_PATHS[`/${slug}/`] = `/market-area/${city}/`;
}
for (const [target, sources] of Object.entries(productMerges)) {
  for (const source of sources) REDIRECTED_PATHS[source] = target;
}

export const isRedirectedPath = (path) => {
  if (!path) return false;
  const clean = path.replace(/^https?:\/\/[^/]+/, '').split(/[?#]/)[0];
  return Boolean(REDIRECTED_PATHS[clean.endsWith('/') ? clean : `${clean}/`]);
};
